CREATE TABLE users (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    username VARCHAR(50) NOT NULL, 
    email VARCHAR(255) NOT NULL, 
    role VARCHAR(20) DEFAULT 'user' NOT NULL, 
    password_hash TEXT NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (role IN ('admin', 'user')), 
    UNIQUE (username), 
    UNIQUE (email)
);

CREATE TABLE providers (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    name VARCHAR(100) NOT NULL, 
    provider_type VARCHAR(50) NOT NULL, 
    base_url TEXT, 
    api_key_env VARCHAR(100), 
    enabled BOOLEAN DEFAULT true NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (name)
);

CREATE TABLE models (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    provider_id INTEGER NOT NULL, 
    model_name VARCHAR(200) NOT NULL, 
    display_name VARCHAR(200) NOT NULL, 
    supports_text BOOLEAN DEFAULT true NOT NULL, 
    supports_streaming BOOLEAN DEFAULT true NOT NULL, 
    supports_vision BOOLEAN DEFAULT false NOT NULL, 
    supports_audio BOOLEAN DEFAULT false NOT NULL, 
    supports_tools BOOLEAN DEFAULT false NOT NULL, 
    supports_json BOOLEAN DEFAULT false NOT NULL, 
    context_window INTEGER, 
    enabled BOOLEAN DEFAULT true NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (provider_id, model_name), 
    FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE CASCADE
);

CREATE TABLE conversations (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    title VARCHAR(100) DEFAULT 'New Chat' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE
);

CREATE TABLE messages (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    conversation_id INTEGER NOT NULL, 
    role VARCHAR(20) NOT NULL, 
    content TEXT NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (role IN ('user', 'assistant')), 
    FOREIGN KEY(conversation_id) REFERENCES conversations (id) ON DELETE CASCADE
);

CREATE TABLE agents (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    name VARCHAR(100) NOT NULL, 
    description TEXT DEFAULT '' NOT NULL, 
    system_prompt TEXT NOT NULL, 
    provider_id INTEGER, 
    model_id INTEGER, 
    temperature NUMERIC(3, 2) DEFAULT '0.70' NOT NULL, 
    internet_enabled BOOLEAN DEFAULT false NOT NULL, 
    multimodal_enabled BOOLEAN DEFAULT false NOT NULL, 
    enabled BOOLEAN DEFAULT true NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (name), 
    FOREIGN KEY(provider_id) REFERENCES providers (id) ON DELETE SET NULL, 
    FOREIGN KEY(model_id) REFERENCES models (id) ON DELETE SET NULL
);

CREATE TABLE skills (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    name VARCHAR(100) NOT NULL, 
    description TEXT DEFAULT '' NOT NULL, 
    enabled BOOLEAN DEFAULT true NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (name)
);

CREATE TABLE agent_skills (
    agent_id INTEGER NOT NULL, 
    skill_id INTEGER NOT NULL, 
    PRIMARY KEY (agent_id, skill_id), 
    FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE CASCADE, 
    FOREIGN KEY(skill_id) REFERENCES skills (id) ON DELETE CASCADE
);

CREATE TABLE mcp_servers (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    name VARCHAR(100) NOT NULL, 
    description TEXT DEFAULT '' NOT NULL, 
    connection_type VARCHAR(20) NOT NULL, 
    command TEXT, 
    url TEXT, 
    enabled BOOLEAN DEFAULT false NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (connection_type IN ('command', 'url')), 
    UNIQUE (name)
);

CREATE TABLE agent_mcps (
    agent_id INTEGER NOT NULL, 
    mcp_server_id INTEGER NOT NULL, 
    PRIMARY KEY (agent_id, mcp_server_id), 
    FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE CASCADE, 
    FOREIGN KEY(mcp_server_id) REFERENCES mcp_servers (id) ON DELETE CASCADE
);

CREATE TABLE workflows (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    name VARCHAR(100) NOT NULL, 
    workflow_type VARCHAR(30) NOT NULL, 
    enabled BOOLEAN DEFAULT true NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (workflow_type IN ('single_agent', 'sequential', 'supervisor', 'reviewer', 'parallel', 'debate')), 
    UNIQUE (name)
);

CREATE TABLE workflow_steps (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    workflow_id INTEGER NOT NULL, 
    agent_id INTEGER, 
    step_order INTEGER NOT NULL, 
    step_name VARCHAR(100) NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (workflow_id, step_order), 
    FOREIGN KEY(workflow_id) REFERENCES workflows (id) ON DELETE CASCADE, 
    FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE SET NULL
);

CREATE TABLE agent_runs (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    conversation_id INTEGER NOT NULL, 
    message_id INTEGER, 
    agent_id INTEGER, 
    workflow_id INTEGER, 
    status VARCHAR(20) NOT NULL, 
    final_response TEXT, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    completed_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    CHECK (status IN ('running', 'completed', 'failed')), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    FOREIGN KEY(conversation_id) REFERENCES conversations (id) ON DELETE CASCADE, 
    FOREIGN KEY(message_id) REFERENCES messages (id) ON DELETE SET NULL, 
    FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE SET NULL, 
    FOREIGN KEY(workflow_id) REFERENCES workflows (id) ON DELETE SET NULL
);

CREATE TABLE agent_events (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER NOT NULL, 
    event_type VARCHAR(50) NOT NULL, 
    title VARCHAR(200) NOT NULL, 
    content TEXT DEFAULT '' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);

CREATE TABLE tool_calls (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER NOT NULL, 
    skill_name VARCHAR(100) NOT NULL, 
    input_summary TEXT DEFAULT '' NOT NULL, 
    output_summary TEXT DEFAULT '' NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (status IN ('running', 'completed', 'failed')), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);

CREATE TABLE mcp_calls (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER NOT NULL, 
    mcp_server_id INTEGER, 
    tool_name VARCHAR(100) NOT NULL, 
    input_summary TEXT DEFAULT '' NOT NULL, 
    output_summary TEXT DEFAULT '' NOT NULL, 
    status VARCHAR(20) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CHECK (status IN ('running', 'completed', 'failed')), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE, 
    FOREIGN KEY(mcp_server_id) REFERENCES mcp_servers (id) ON DELETE SET NULL
);

CREATE TABLE attachments (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    message_id INTEGER, 
    file_name TEXT NOT NULL, 
    mime_type VARCHAR(150) NOT NULL, 
    storage_path TEXT NOT NULL, 
    size_bytes INTEGER NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    FOREIGN KEY(message_id) REFERENCES messages (id) ON DELETE CASCADE
);

CREATE TABLE artifacts (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER, 
    attachment_id INTEGER, 
    artifact_type VARCHAR(50) NOT NULL, 
    title VARCHAR(200) NOT NULL, 
    content TEXT NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE, 
    FOREIGN KEY(attachment_id) REFERENCES attachments (id) ON DELETE CASCADE
);

CREATE TABLE sources (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER, 
    url TEXT NOT NULL, 
    title TEXT DEFAULT '' NOT NULL, 
    snippet TEXT DEFAULT '' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);

CREATE TABLE settings (
    key VARCHAR(100) NOT NULL, 
    value TEXT NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (key)
);

