ALTER TABLE agents ADD COLUMN agentic_mode BOOLEAN DEFAULT false NOT NULL;

CREATE TABLE agent_tool_permissions (
    agent_id INTEGER NOT NULL, 
    tool_name VARCHAR(100) NOT NULL, 
    allowed BOOLEAN DEFAULT true NOT NULL, 
    PRIMARY KEY (agent_id, tool_name), 
    FOREIGN KEY(agent_id) REFERENCES agents (id) ON DELETE CASCADE
);

CREATE TABLE tool_approvals (
    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    agent_run_id INTEGER NOT NULL, 
    user_id INTEGER NOT NULL, 
    conversation_id INTEGER NOT NULL, 
    tool_name VARCHAR(100) NOT NULL, 
    args JSON DEFAULT '{}'::json NOT NULL, 
    status VARCHAR(20) DEFAULT 'pending' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    decided_at TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (id), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE, 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    FOREIGN KEY(conversation_id) REFERENCES conversations (id) ON DELETE CASCADE
);

CREATE INDEX ix_tool_approvals_pending ON tool_approvals (status, user_id);

CREATE TABLE agent_run_state (
    agent_run_id INTEGER NOT NULL, 
    messages JSON DEFAULT '[]'::json NOT NULL, 
    iterations INTEGER DEFAULT 0 NOT NULL, 
    tool_call_count INTEGER DEFAULT 0 NOT NULL, 
    thought_text TEXT DEFAULT '' NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (agent_run_id), 
    FOREIGN KEY(agent_run_id) REFERENCES agent_runs (id) ON DELETE CASCADE
);

CREATE TABLE app_settings (
    key VARCHAR(100) NOT NULL, 
    value JSON DEFAULT '{}'::json NOT NULL, 
    PRIMARY KEY (key)
);

