    id INTEGER GENERATED BY DEFAULT AS IDENTITY, 
    user_id INTEGER NOT NULL, 
    connector_slug VARCHAR(50) NOT NULL, 
    credentials_encrypted TEXT NOT NULL, 
    display_name TEXT DEFAULT '' NOT NULL, 
    status VARCHAR(20) DEFAULT 'connected' NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL, 
    PRIMARY KEY (id), 
    CONSTRAINT uq_connector_accounts_user_slug UNIQUE (user_id, connector_slug), 
    FOREIGN KEY(user_id) REFERENCES users (id) ON DELETE CASCADE, 
    FOREIGN KEY(connector_slug) REFERENCES connectors (slug) ON DELETE CASCADE
);

